stuff_sexGenes <- data.frame(revigo.data_sexGenes);
names(stuff_sexGenes) <- revigo.names;

stuff_sexGenes$value <- as.numeric( as.character(stuff_sexGenes$value) );
stuff_sexGenes$frequency <- as.numeric( as.character(stuff_sexGenes$frequency) );
stuff_sexGenes$uniqueness <- as.numeric( as.character(stuff_sexGenes$uniqueness) );
stuff_sexGenes$dispensability <- as.numeric( as.character(stuff_sexGenes$dispensability) );

# by default, outputs to a PDF file
pdf( file="revigo_treemap_sexGenes.pdf", width=16, height=9 ) # width and height are in inches
# check the tmPlot command documentation for all possible parameters - there are a lot more
treemap(stuff_sexGenes,
	index = c("representative","description"),
	vSize = "value",
	type = "categorical",
	fontsize.labels = c(0,10),
	fontsize.legend = 10,
	vColor = "representative",
	palette = colorRampPalette(c("red4", "indianred", "gray73"))(30),
	title = "Map of Enriched GO Biological Processes: Sex-related Genes",
	title.legend = "Parent Nodes",	
	inflate.labels = FALSE,      # set this to TRUE for space-filling group labels - good for posters
	lowerbound.cex.labels = 0.1,   # try to draw as many labels as possible (still, some small squares may not get a label)
	bg.labels = "#CCCCCCAA",   # define background color of group labels
								 # "#CCCCCC00" is fully transparent, "#CCCCCCAA" is semi-transparent grey, NA is opaque				 
	position.legend = "right"
)
dev.off()

